550	// ServeHTTP is the entry point for all HTTP requests.
551	func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
552		start := time.Now()
553	
554		// If there are listener wrappers that process tls connections but don't return a *tls.Conn, this field will be nil.
555		if r.TLS == nil {
556			if tlsConnStateFunc, ok := r.Context().Value(tlsConnectionStateFuncCtxKey).(func() *tls.ConnectionState); ok {
557				r.TLS = tlsConnStateFunc()
558			}
559		}
560	
561		// enable full-duplex for HTTP/1, ensuring the entire
562		// request body gets consumed before writing the response
563		if s.EnableFullDuplex && r.ProtoMajor == 1 {
564			if err := http.NewResponseController(w).EnableFullDuplex(); err != nil { //nolint:bodyclose
565				if c := s.logger.Check(zapcore.WarnLevel, "failed to enable full duplex"); c != nil {
566					c.Write(zap.Error(err))
567				}
568			}
569		}
