574		// reset on every successful read/write, so this doesn't affect
575		// legitimately slow clients as long as they keep making progress.
576		// hardDeadline, anchored to this handler's start, caps how far
577		// that reset can push the deadline out, so an explicitly configured
578		// ReadTimeout/WriteTimeout ceiling still applies on top instead of
579		// being silently overwritten by the first read/write.
580		rc := http.NewResponseController(w)
581		var readHardDeadline, writeHardDeadline time.Time
582		if s.ReadTimeout > 0 {
583			readHardDeadline = start.Add(time.Duration(s.ReadTimeout))
584		}
585		if s.WriteTimeout > 0 {
586			writeHardDeadline = start.Add(time.Duration(s.WriteTimeout))
587		}
588		var idleReader *IdleTimeoutReader
589		var idleWriter *IdleTimeoutWriter
590		if s.ReadIdleTimeout > 0 && r.Body != nil {
591			idleReader = &IdleTimeoutReader{
592				ReadCloser: r.Body,
593				Ctrl:       rc,
594				Deadline: IdleDeadline{
595					Start:        start,
596					Timeout:      time.Duration(s.ReadIdleTimeout),
597					MinRate:      s.ReadMinRate,
598					HardDeadline: readHardDeadline,
599				},
600				Logger:        s.logger,
601				DrainDeadline: r.ProtoMajor == 1 && r.ContentLength != 0,
602			}
603			defer idleReader.HandlerDone()
604			r.Body = idleReader
605		}
606		if s.WriteIdleTimeout > 0 {
607			idleWriter = &IdleTimeoutWriter{
608				ResponseWriterWrapper: &ResponseWriterWrapper{ResponseWriter: w},
609				Ctrl:                  rc,
610				Deadline: IdleDeadline{
611					Start:        start,
612					Timeout:      time.Duration(s.WriteIdleTimeout),
613					MinRate:      s.WriteMinRate,
614					HardDeadline: writeHardDeadline,
615				},
616				MaxChunk:           s.MaxWriteChunk,
617				Logger:             s.logger,
618				ClearBetweenWrites: r.ProtoMajor == 2,
619			}
620			defer idleWriter.HandlerDone()
621			w = idleWriter
622		}
623	
624		// set the Server header
625		h := w.Header()
626		h["Server"] = serverHeader
627	
628		// advertise HTTP/3, if enabled
629		if s.h3server != nil && r.ProtoMajor < 3 {
630			if err := s.h3server.SetQUICHeaders(h); err != nil {
631				lvl := zapcore.ErrorLevel
632				if errors.Is(err, http3.ErrNoAltSvcPort) {
633					lvl = zapcore.DebugLevel
634				}
635				if c := s.logger.Check(lvl, "setting HTTP/3 Alt-Svc header"); c != nil {
636					c.Write(zap.Error(err))
637				}
638			}
639		}
640	
641		// prepare internals of the request for the handler pipeline
642		repl := caddy.NewReplacer()
643		r = prepareRequest(r, repl, w, s, idleTimeouts{reader: idleReader, writer: idleWriter})
644	
645		// clone the request for logging purposes before it enters any handler chain;
646		// this is necessary to capture the original request in case it gets modified
647		// during handling (cloning the request and using .WithLazy is considerably
648		// faster than using .With, which will JSON-encode the request immediately)
649		shouldLogCredentials := s.Logs != nil && s.Logs.ShouldLogCredentials
650		loggableReq := zap.Object("request", LoggableHTTPRequest{
651			Request:              r.Clone(r.Context()),
652			ShouldLogCredentials: shouldLogCredentials,
653		})
654		errLog := s.errorLogger.WithLazy(loggableReq)
655	
656		var duration time.Duration
657		var wrec ResponseRecorder
658		var writeErr error
659	
660		if s.shouldLogRequest(r) {
661			wrec = NewResponseRecorder(w, nil, nil)
662			w = wrec
663	
664			// wrap the request body in a LengthReader
665			// so we can track the number of bytes read from it
666			var bodyReader *lengthReader
667			if r.Body != nil {
668				bodyReader = &lengthReader{Source: r.Body}
669				r.Body = bodyReader
670				// should always be true, private interface can only be referenced in the same package
671				if setReadSizer, ok := wrec.(interface{ setReadSize(*int) }); ok {
672					setReadSizer.setReadSize(&bodyReader.Length)
673				}
674			}
675	
676			// capture the original version of the request
677			accLog := s.accessLogger.WithLazy(loggableReq)
678	
679			defer s.logRequest(accLog, r, wrec, &duration, &writeErr, repl, bodyReader, shouldLogCredentials)
680	
681			// if the request went past the write timeout, flush so the access log can
682			// see the write error. deferred because flushing before the error routes
683			// run would commit a 200 and lose the error status. it sits after the
684			// access log defer so it still runs first.
685			defer func() {
686				if s.WriteTimeout <= 0 ||
687					r.ProtoMajor != 1 ||
688					duration < time.Duration(s.WriteTimeout) {
689					return
690				}
691				// over wrec, not the rc above: this reaches the recorder's
692				// FlushError, which skips buffered responses (#6144); rc sits
693				// below the recorder and would flush them anyway.
694				flushErr := http.NewResponseController(wrec).Flush()
695				if flushErr != nil &&
696					!errors.Is(flushErr, http.ErrHijacked) &&
697					!errors.Is(flushErr, http.ErrNotSupported) {
698					writeErr = flushErr
699				}
700			}()
701		}
702	
703		// guarantee ACME HTTP challenges; handle them separately from any user-defined handlers
704		if s.tlsApp.HandleHTTPChallenge(w, r) {
705			duration = time.Since(start)
706			return
707		}
708	
709		err := s.serveHTTP(w, r)
710		duration = time.Since(start)
711	
712		if err == nil {
713			return
714		}
715	
716		// restore original request before invoking error handler chain (issue #3717)
717		// NOTE: this does not restore original headers if modified (for efficiency)
718		origReq, ok := r.Context().Value(OriginalRequestCtxKey).(http.Request)
719		if ok {
720			r.Method = origReq.Method
721			r.RemoteAddr = origReq.RemoteAddr
722			r.RequestURI = origReq.RequestURI
723			cloneURL(origReq.URL, r.URL)
724		}
725	
726		// prepare the error log
727		errLog = errLog.With(zap.Duration("duration", duration))
728		errLoggers := []*zap.Logger{errLog}
729		if s.Logs != nil {
730			errLoggers = s.Logs.wrapLogger(errLog, r)
731		}
732	
733		// get the values that will be used to log the error
734		errStatus, errMsg, errFields := errLogValues(err)
735	
736		// add HTTP error information to request context
737		r = s.Errors.WithError(r, err)
738	
739		var fields []zapcore.Field
740		if s.Errors != nil && len(s.Errors.Routes) > 0 {
741			// execute user-defined error handling route
742			if err2 := s.errorHandlerChain.ServeHTTP(w, r); err2 == nil {
743				// user's error route handled the error response successfully, so now just log the error
744				for _, logger := range errLoggers {
745					if c := logger.Check(zapcore.DebugLevel, errMsg); c != nil {
746						if fields == nil {
747							fields = errFields()
748						}
749						c.Write(fields...)
750					}
751				}
752			} else {
753				// well... this is awkward
754				for _, logger := range errLoggers {
755					if c := logger.Check(zapcore.ErrorLevel, "error handling handler error"); c != nil {
756						if fields == nil {
757							fields = errFields()
758							fields = append([]zapcore.Field{
759								zap.String("error", err2.Error()),
760								zap.Namespace("first_error"),
761								zap.String("msg", errMsg),
762							}, fields...)
763						}
764						c.Write(fields...)
765					}
766				}
767				if handlerErr, ok := err.(HandlerError); ok {
768					w.WriteHeader(handlerErr.StatusCode)
769				} else {
770					w.WriteHeader(http.StatusInternalServerError)
771				}
772			}
773		} else {
774			logLevel := zapcore.DebugLevel
775			if errStatus >= 500 {
776				logLevel = zapcore.ErrorLevel
777			}
778	
779			for _, logger := range errLoggers {
780				if c := logger.Check(logLevel, errMsg); c != nil {
781					if fields == nil {
782						fields = errFields()
783					}
784					c.Write(fields...)
785				}
786			}
787			w.WriteHeader(errStatus)
788		}
789	}
