416	// provisionHeaderAliasAllowlist validates entries for a header-alias
417	// allowlist (ExpectedUnderscoreHeaders or ExpectedDotHeaders) and builds
418	// the precomputed maps and prefix rules used by the hot-path filter in
419	// serveHTTP. sep is the separator the entries must contain ('_' or '.');
420	// directive is the Caddyfile/JSON name used in error messages.
421	func provisionHeaderAliasAllowlist(entries []string, sep rune, directive string) (exactAllow, exactDrop map[string]struct{}, prefixRules []aliasPrefixRule, err error) {
422		exactAllow = make(map[string]struct{}, len(entries))
423		exactDrop = make(map[string]struct{}, len(entries))
424	
425		for _, entry := range entries {
426			// Reject non-ASCII bytes: Go's HTTP parser returns 400 for
427			// non-ASCII header names, so such entries can never match.
428			for i := 0; i < len(entry); i++ {
429				if entry[i] >= 0x80 {
430					return nil, nil, nil, fmt.Errorf("%s: entry %q contains non-ASCII characters", directive, entry)
431				}
432			}
433	
434			isGlob := strings.HasSuffix(entry, "*")
435			name := entry
436			if isGlob {
437				name = strings.TrimSuffix(entry, "*")
438			}
439	
440			// Reject entries with '*' not at the trailing position.
441			if strings.ContainsRune(name, '*') {
442				return nil, nil, nil, fmt.Errorf("%s: entry %q has '*' in an invalid position (only a trailing '*' is allowed)", directive, entry)
443			}
444	
445			// The name (without trailing '*') must contain at least one separator.
446			if !strings.ContainsRune(name, sep) {
447				return nil, nil, nil, fmt.Errorf("%s: entry %q does not contain a %q", directive, entry, sep)
448			}
449	
450			canonAllow := http.CanonicalHeaderKey(name)
451			canonDrop := http.CanonicalHeaderKey(strings.ReplaceAll(name, string(sep), "-"))
452	
453			if isGlob {
454				prefixRules = append(prefixRules, aliasPrefixRule{
455					allow: canonAllow,
456					drop:  canonDrop,
457				})
458			} else {
459				exactAllow[canonAllow] = struct{}{}
460				exactDrop[canonDrop] = struct{}{}
461			}
462		}
463	
464		return exactAllow, exactDrop, prefixRules, nil
465	}
