507	// init should be called before we write a response, if rw.buf has contents.
508	func (rw *responseWriter) init() {
509		// Don't initialize encoder for responses that must not be encoded.
510		if rw.disabled {
511			return
512		}
513	
514		hdr := rw.Header()
515	
516		if hdr.Get("Content-Encoding") == "" && isEncodeAllowed(hdr) &&
517			rw.config.Match(rw) {
518			rw.w = rw.config.writerPools[rw.encodingName].Get().(Encoder)
519			rw.w.Reset(rw.ResponseWriter)
