313	func isSSE(contentType string) bool {
314		if len(contentType) < len(sseMediaType) || !strings.EqualFold(contentType[:len(sseMediaType)], sseMediaType) {
315			return false
316		}
317	
318		// After the media type, allow only optional whitespace followed by the
319		// end of the value or a parameter separator, so a longer type such as
320		// "text/event-streamfoo" or garbage like "text/event-stream nonsense"
321		// does not match. TrimLeft on the tail does not allocate.
322		rest := strings.TrimLeft(contentType[len(sseMediaType):], " \t")
323	
324		return rest == "" || rest[0] == ';'
325	}
