364	// Write writes to the response. If the response qualifies,
365	// it is encoded using the encoder, which is initialized
366	// if not done so already.
367	func (rw *responseWriter) Write(p []byte) (int, error) {
368		// ignore zero data writes, probably head request
369		if len(p) == 0 {
370			return 0, nil
371		}
372	
373		// WriteHeader wasn't called and is a CONNECT request, treat it as a success.
374		// otherwise, determine if the response should be compressed.
375		if rw.isConnect && !rw.wroteHeader && rw.statusCode == 0 {
376			rw.WriteHeader(http.StatusOK)
377		}
378		if !rw.wroteHeader && rw.statusCode == 0 && caddyhttp.IsIncremental(rw.Header()) {
379			if rw.Header().Get("Content-Type") == "" {
380				rw.Header().Set("Content-Type", http.DetectContentType(p))
381			}
382			rw.WriteHeader(http.StatusOK)
383		}
384	
385		// sniff content-type and determine content-length
386		if !rw.wroteHeader && rw.config.MinLength > 0 {
387			var gtMinLength bool
388			if len(p) > rw.config.MinLength {
389				gtMinLength = true
390			} else if cl, err := strconv.Atoi(rw.Header().Get("Content-Length")); err == nil && cl > rw.config.MinLength {
391				gtMinLength = true
392			}
393	
394			if gtMinLength {
395				if rw.Header().Get("Content-Type") == "" {
396					rw.Header().Set("Content-Type", http.DetectContentType(p))
397				}
398				rw.init()
399			}
400		}
401	
402		// before we write to the response, we need to make
403		// sure the header is written exactly once; we do
404		// that by checking if a status code has been set,
405		// and if so, that means we haven't written the
406		// header OR the default status code will be written
407		// by the standard library
408		if !rw.wroteHeader {
409			if rw.statusCode != 0 {
410				rw.ResponseWriter.WriteHeader(rw.statusCode)
411			}
412			rw.wroteHeader = true
413		}
414	
415		var n int
416		var err error
417		if rw.w != nil {
418			n, err = rw.w.Write(p)
419		} else {
420			n, err = rw.ResponseWriter.Write(p)
421		}
422		if err != nil || !rw.incremental {
423			return n, err
424		}
425		return n, rw.FlushError()
426	}
