114	// EXPERIMENTAL: Subject to change or removal.
115	func (ir Intercept) ServeHTTP(w http.ResponseWriter, r *http.Request, next caddyhttp.Handler) error {
116		buf := bufPool.Get().(*bytes.Buffer)
117		buf.Reset()
118		defer bufPool.Put(buf)
119	
120		repl := r.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)
121		rec := interceptedResponseHandler{replacer: repl}
122		rec.ResponseRecorder = caddyhttp.NewResponseRecorder(w, buf, func(status int, header http.Header) bool {
123			// see if any response handler is configured for this original response
124			for i, rh := range ir.HandleResponse {
125				if rh.Match != nil && !rh.Match.Match(status, header) {
126					continue
127				}
128				rec.handler = rh
129				rec.handlerIndex = i
130	
131				// if configured to only change the status code,
132				// buffer the response so we can substitute the status
133				if statusCodeStr := rh.StatusCode.String(); statusCodeStr != "" {
134					sc, err := strconv.Atoi(repl.ReplaceAll(statusCodeStr, ""))
135					if err != nil {
136						rec.statusCode = http.StatusInternalServerError
137					} else {
138						rec.statusCode = sc
139					}
140	
141					return true
142				}
143	
144				return rec.statusCode == 0
145			}
146	
147			return false
148		})
149	
150		if err := next.ServeHTTP(rec, r); err != nil {
151			return err
152		}
153		if !rec.Buffered() {
154			return nil
155		}
156	
157		// set up the replacer so that parts of the original response can be
158		// used for routing decisions
159		for field, value := range rec.Header() {
160			repl.Set("http.intercept.header."+field, strings.Join(value, ","))
161		}
162		repl.Set("http.intercept.status_code", rec.Status())
163	
164		if c := ir.logger.Check(zapcore.DebugLevel, "handling response"); c != nil {
165			c.Write(zap.Int("handler", rec.handlerIndex))
166		}
167	
168		// replace_status only: no routes to execute, just substitute status and write body
169		if rec.handler.Routes == nil {
170			if rec.statusCode == 0 {
171				w.WriteHeader(rec.Status())
172			} else {
173				w.WriteHeader(rec.statusCode)
174			}
175	
176			if buf.Len() > 0 {
177				_, err := io.Copy(w, buf)
178	
179				return err
180			}
181	
182			return nil
183		}
184	
185		// response recorder doesn't create a new copy of the original headers, they're
186		// present in the original response writer
187		// create a new recorder to see if any response body from the new handler is present,
188		// if not, use the already buffered response body
189		recorder := caddyhttp.NewResponseRecorder(w, nil, nil)
190		if err := rec.handler.Routes.Compile(emptyHandler).ServeHTTP(recorder, r); err != nil {
191			return err
192		}
193	
194		// no new response status and the status is not 0
195		if recorder.Status() == 0 && rec.Status() != 0 {
196			w.WriteHeader(rec.Status())
197		}
198	
199		// no new response body and there is some in the original response
200		// TODO: what if the new response doesn't have a body by design?
201		// see: https://github.com/caddyserver/caddy/pull/6232#issue-2235224400
202		if recorder.Size() == 0 && buf.Len() > 0 {
203			_, err := io.Copy(w, buf)
204			return err
205		}
206		return nil
207	}
