214	// UnmarshalCaddyfile sets up the handler from Caddyfile tokens. Syntax:
215	//
216	//	intercept [<matcher>] {
217	//	    # intercept original responses
218	//	    @name {
219	//	        status <code...>
220	//	        header <field> [<value>]
221	//	    }
222	//	    replace_status [<matcher>] <status_code>
223	//	    handle_response [<matcher>] {
224	//	        <directives...>
225	//	    }
226	//	}
227	//
228	// The FinalizeUnmarshalCaddyfile method should be called after this
229	// to finalize parsing of "handle_response" blocks, if possible.
230	//
231	// EXPERIMENTAL: Subject to change or removal.
232	func (i *Intercept) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
233		// collect the response matchers defined as subdirectives
234		// prefixed with "@" for use with "handle_response" blocks
235		i.responseMatchers = make(map[string]caddyhttp.ResponseMatcher)
236	
237		d.Next() // consume the directive name
238		for d.NextBlock(0) {
239			// if the subdirective has an "@" prefix then we
240			// parse it as a response matcher for use with "handle_response"
241			if strings.HasPrefix(d.Val(), matcherPrefix) {
242				err := caddyhttp.ParseNamedResponseMatcher(d.NewFromNextSegment(), i.responseMatchers)
243				if err != nil {
244					return err
245				}
246				continue
247			}
248	
249			switch d.Val() {
250			case "handle_response":
251				// delegate the parsing of handle_response to the caller,
252				// since we need the httpcaddyfile.Helper to parse subroutes.
253				// See h.FinalizeUnmarshalCaddyfile
254				i.handleResponseSegments = append(i.handleResponseSegments, d.NewFromNextSegment())
255	
256			case "replace_status":
257				args := d.RemainingArgs()
258				if len(args) != 1 && len(args) != 2 {
259					return d.Errf("must have one or two arguments: an optional response matcher, and a status code")
260				}
261	
262				responseHandler := caddyhttp.ResponseHandler{}
263	
264				if len(args) == 2 {
265					if !strings.HasPrefix(args[0], matcherPrefix) {
266						return d.Errf("must use a named response matcher, starting with '@'")
267					}
268					foundMatcher, ok := i.responseMatchers[args[0]]
269					if !ok {
270						return d.Errf("no named response matcher defined with name '%s'", args[0][1:])
271					}
272					responseHandler.Match = &foundMatcher
273					responseHandler.StatusCode = caddyhttp.WeakString(args[1])
274				} else if len(args) == 1 {
275					responseHandler.StatusCode = caddyhttp.WeakString(args[0])
276				}
277	
278				// make sure there's no block, cause it doesn't make sense
279				if nesting := d.Nesting(); d.NextBlock(nesting) {
280					return d.Errf("cannot define routes for 'replace_status', use 'handle_response' instead.")
281				}
282	
283				i.HandleResponse = append(
284					i.HandleResponse,
285					responseHandler,
286				)
287	
288			default:
289				return d.Errf("unrecognized subdirective %s", d.Val())
290			}
291		}
292	
293		return nil
294	}
