	closeNow := func() {
		if _, ok := hosts.References(key); ok {
			return
		}

		detachedStreams.Lock()
		toClose := make([]*upgradedStream, 0, len(detachedStreams.streams[key]))
		for s := range detachedStreams.streams[key] {
