30		// plug in Caddy modules here
31		_ "github.com/caddyserver/caddy/v2/modules/standard"
32	)
33	
34	// Config store any configuration required to make the tests run
35	type Config struct {
36		// Port we expect caddy to listening on
37		AdminPort int
38		// Certificates we expect to be loaded before attempting to run the tests
39		Certificates []string
40		// TestRequestTimeout is the time to wait for a http request to
41		TestRequestTimeout time.Duration
42		// LoadRequestTimeout is the time to wait for the config to be loaded against the caddy server
43		LoadRequestTimeout time.Duration
44	}
45	
46	// Default testing values
47	var Default = Config{
48		AdminPort:          2999, // different from what a real server also running on a developer's machine might be
49		Certificates:       []string{"/caddy.localhost.crt", "/caddy.localhost.key"},
50		TestRequestTimeout: 5 * time.Second,
51		LoadRequestTimeout: 5 * time.Second,
52	}
53	
54	var (
55		matchKey  = regexp.MustCompile(`(/[\w\d\.]+\.key)`)
56		matchCert = regexp.MustCompile(`(/[\w\d\.]+\.crt)`)
57	)
58	
59	// Tester represents an instance of a test client.
60	type Tester struct {
61		Client       *http.Client
62		configLoaded bool
63		t            testing.TB
64		config       Config
65	}
66	
67	// NewTester will create a new testing client with an attached cookie jar
68	func NewTester(t testing.TB) *Tester {
69		jar, err := cookiejar.New(nil)
70		if err != nil {
71			t.Fatalf("failed to create cookiejar: %s", err)
72		}
73	
74		return &Tester{
75			Client: &http.Client{
76				Transport: CreateTestingTransport(),
77				Jar:       jar,
78				Timeout:   Default.TestRequestTimeout,
79			},
80			configLoaded: false,
81			t:            t,
82			config:       Default,
83		}
84	}
85	
86	// WithDefaultOverrides this will override the default test configuration with the provided values.
87	func (tc *Tester) WithDefaultOverrides(overrides Config) *Tester {
88		if overrides.AdminPort != 0 {
89			tc.config.AdminPort = overrides.AdminPort
90		}
91		if len(overrides.Certificates) > 0 {
92			tc.config.Certificates = overrides.Certificates
93		}
94		if overrides.TestRequestTimeout != 0 {
95			tc.config.TestRequestTimeout = overrides.TestRequestTimeout
96			tc.Client.Timeout = overrides.TestRequestTimeout
97		}
98		if overrides.LoadRequestTimeout != 0 {
99			tc.config.LoadRequestTimeout = overrides.LoadRequestTimeout
100		}
101	
102		return tc
103	}
104	
105	type configLoadError struct {
106		Response string
107	}
108	
109	func (e configLoadError) Error() string { return e.Response }
110	
111	func timeElapsed(start time.Time, name string) {
112		elapsed := time.Since(start)
113		log.Printf("%s took %s", name, elapsed)
114	}
115	
116	// InitServer this will configure the server with a configurion of a specific
117	// type. The configType must be either "json" or the adapter type.
118	func (tc *Tester) InitServer(rawConfig string, configType string) {
119		if err := tc.initServer(rawConfig, configType); err != nil {
120			tc.t.Logf("failed to load config: %s", err)
121			tc.t.Fail()
122		}
123		if err := tc.ensureConfigRunning(rawConfig, configType); err != nil {
124			tc.t.Logf("failed ensuring config is running: %s", err)
125			tc.t.Fail()
126		}
127	}
128	
129	// InitServer this will configure the server with a configurion of a specific
130	// type. The configType must be either "json" or the adapter type.
131	func (tc *Tester) initServer(rawConfig string, configType string) error {
132		if testing.Short() {
133			tc.t.SkipNow()
134			return nil
135		}
136	
137		err := validateTestPrerequisites(tc)
138		if err != nil {
139			tc.t.Skipf("skipping tests as failed integration prerequisites. %s", err)
140			return nil
141		}
142	
143		tc.t.Cleanup(func() {
144			if tc.t.Failed() && tc.configLoaded {
145				res, err := http.Get(fmt.Sprintf("http://localhost:%d/config/", tc.config.AdminPort))
146				if err != nil {
147					tc.t.Log("unable to read the current config")
148					return
149				}
150				defer res.Body.Close()
151				body, _ := io.ReadAll(res.Body)
152	
153				var out bytes.Buffer
154				_ = json.Indent(&out, body, "", "  ")
155				tc.t.Logf("----------- failed with config -----------\n%s", out.String())
156			}
157		})
158	
159		rawConfig = prependCaddyFilePath(rawConfig)
160		// normalize JSON config
161		if configType == "json" {
162			tc.t.Logf("Before: %s", rawConfig)
163			var conf any
164			if err := json.Unmarshal([]byte(rawConfig), &conf); err != nil {
165				return err
166			}
167			c, err := json.Marshal(conf)
168			if err != nil {
169				return err
170			}
171			rawConfig = string(c)
172			tc.t.Logf("After: %s", rawConfig)
173		}
174		client := &http.Client{
175			Timeout: tc.config.LoadRequestTimeout,
176		}
177		start := time.Now()
178		req, err := http.NewRequest("POST", fmt.Sprintf("http://localhost:%d/load", tc.config.AdminPort), strings.NewReader(rawConfig))
179		if err != nil {
180			tc.t.Errorf("failed to create request. %s", err)
181			return err
182		}
183	
184		if configType == "json" {
185			req.Header.Add("Content-Type", "application/json")
186		} else {
187			req.Header.Add("Content-Type", "text/"+configType)
188		}
189	
190		res, err := client.Do(req) //nolint:gosec // no SSRF because URL is hard-coded to localhost, and port comes from config
191		if err != nil {
192			tc.t.Errorf("unable to contact caddy server. %s", err)
193			return err
194		}
195		timeElapsed(start, "caddytest: config load time")
196	
197		defer res.Body.Close()
198		body, err := io.ReadAll(res.Body)
199		if err != nil {
200			tc.t.Errorf("unable to read response. %s", err)
201			return err
