				body = "stream_detached"
			}
			tester.InitServer(fmt.Sprintf(`
			{
				admin localhost:2999
				http_port 9080
				https_port 9443
				grace_period 1ns
			}
			http://localhost:9080 {
				encode gzip zstd
				intercept {
					# matches every response, including the 101 and the 2xx of CONNECT
					handle_response {
						respond "intercepted" 418
					}
