// h2ExtendedConnect opens a WebSocket over HTTP/2 through caddy with an
// extended CONNECT request (RFC 8441), returning the writer and reader of the
// stream.
func h2ExtendedConnect(t *testing.T, path string) (io.Writer, *bufio.Reader, func()) {
	t.Helper()

	tr := &http2.Transport{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: true, ServerName: "localhost"}, //nolint:gosec
	}
	pr, pw := io.Pipe()
	req, err := http.NewRequest(http.MethodConnect, "https://127.0.0.1:9443"+path, pr)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set(":protocol", "websocket")
	req.Header.Set("Sec-WebSocket-Version", "13")

	resp, err := tr.RoundTrip(req)
	if err != nil {
		t.Fatalf("extended CONNECT: %v", err)
	}
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		t.Fatalf("status = %d, want 200; body: %s", resp.StatusCode, body)
	}
	return pw, bufio.NewReader(resp.Body), func() {
		pw.Close()
		resp.Body.Close()
		tr.CloseIdleConnections()
	}
}

func readExactly(t *testing.T, r io.Reader, n int) string {
	t.Helper()

	buf := make([]byte, n)
	done := make(chan error, 1)
	go func() {
		_, err := io.ReadFull(r, buf)
		done <- err
	}()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("reading from the stream: %v", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("timed out reading from the stream")
	}
	return string(buf)
}

func TestStreamExtendedConnectOverH2(t *testing.T) {
	for _, tc := range []struct {
		name string
		body string
	}{
		{name: "default"},
		{name: "detached", body: "stream_detached"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			backend := newUpgradeBackend(t)
			tester := caddytest.NewTester(t)
			site := func(marker string) string {
				return fmt.Sprintf(`
				{
					admin localhost:2999
					http_port 9080
					https_port 9443
					grace_period 1ns
					skip_install_trust
				}
				localhost:9443 {
					tls /caddy.localhost.crt /caddy.localhost.key
					header X-Config %s
					encode gzip
					intercept {
						handle_response {
							respond "intercepted" 418
						}
					}
					reverse_proxy %s {
						%s
					}
				}`, marker, backend.addr(), tc.body)
			}
			tester.InitServer(site("one"), "caddyfile")

			w, r, closeStream := h2ExtendedConnect(t, "/ws")
			defer closeStream()

			if _, err := io.WriteString(w, "over h2"); err != nil {
				t.Fatal(err)
			}
			if got := readExactly(t, r, len("over h2")); got != "over h2" {
				t.Fatalf("echo = %q", got)
			}

			if tc.body == "" {
				return
			}

			// detached streams are kept through a reload
			tester.InitServer(site("two"), "caddyfile")
			if _, err := io.WriteString(w, "after reload"); err != nil {
				t.Fatal(err)
			}
			if got := readExactly(t, r, len("after reload")); got != "after reload" {
				t.Fatalf("echo after reload = %q", got)
			}
		})
	}
}

