			continue
		}
		if v, ok := settings.Value(http2.SettingEnableConnectProtocol); !ok || v != 1 {
			t.Fatal("the server doesn't support extended CONNECT")
		}
		if err := fr.WriteSettingsAck(); err != nil {
			t.Fatal(err)
		}
		break
