package intercept

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/caddy/v2/modules/caddyhttp"
)

// interceptEverything is an Intercept with a handler for any response that
// replaces it, so any response it buffers would be replaced.
func interceptEverything() Intercept {
	return Intercept{
		HandleResponse: []caddyhttp.ResponseHandler{{
			Routes: caddyhttp.RouteList{{
				HandlersRaw: nil,
			}},
		}},
	}
}

func TestInterceptDoesNotBufferTunnelAndUpgradeResponses(t *testing.T) {
	for i, tc := range []struct {
		name         string
		method       string
		status       int
		wantBuffered bool
	}{
		{name: "regular response", method: http.MethodGet, status: http.StatusOK, wantBuffered: true},
		{name: "upgrade", method: http.MethodGet, status: http.StatusSwitchingProtocols},
		{name: "established tunnel", method: http.MethodConnect, status: http.StatusOK},
		{name: "failed tunnel", method: http.MethodConnect, status: http.StatusBadGateway, wantBuffered: true},
	} {
		repl := caddy.NewReplacer()
		req := httptest.NewRequest(tc.method, "http://example.com/", nil)
		req = req.WithContext(context.WithValue(req.Context(), caddy.ReplacerCtxKey, repl))
		rec := httptest.NewRecorder()

		var written int
		err := interceptEverything().ServeHTTP(rec, req, caddyhttp.HandlerFunc(func(w http.ResponseWriter, r *http.Request) error {
			w.WriteHeader(tc.status)
			written = 1
			return nil
		}))
		// an intercepted response runs the (empty) routes of the handler;
		// the point is whether the response reached the client untouched
		_ = err

		if written != 1 {
			t.Fatalf("Test %d (%s): the handler didn't run", i, tc.name)
		}
		reachedClient := rec.Code == tc.status && rec.Flushed || (tc.status == http.StatusSwitchingProtocols && rec.Code == tc.status)
		if tc.wantBuffered && rec.Code != tc.status && rec.Code != 200 {
			t.Errorf("Test %d (%s): unexpected status %d", i, tc.name, rec.Code)
		}
		if !tc.wantBuffered && !reachedClient && rec.Code != tc.status {
			t.Errorf("Test %d (%s): the response with status %d did not reach the client directly (got %d)", i, tc.name, tc.status, rec.Code)
		}
	}
}

