	h := &streamHarness{
		client:  client,
		backend: backend,
		stream:  newUpgradedStream(opts, proxyUser, proxyBackend),
		done:    make(chan struct{}),
	}
	go func() {
		defer close(h.done)
		h.stream.run(zap.NewNop(), new(sync.WaitGroup), reqDone, buffered)
	}()
	return h
}

