			}
		}`, wantErr: true},
		{input: `reverse_proxy localhost:8080 {
			stream_logs {
				colour red
			}
		}`, wantErr: true},
		{input: `reverse_proxy localhost:8080 {
			stream_logs {
				level info
			}
